#ifndef LRU_CACHE_H
#define LRU_CACHE_H

#include <unordered_map>
#include <list>
#include <optional>
#include <cstddef>
#include <stdexcept>
#include <utility>

template<class K, class V>
class LRUCache {
public:
    // Explicit capacity; throws std::invalid_argument if capacity is 0.
    explicit LRUCache(std::size_t capacity)
        : capacity_(capacity)
    {
        if (capacity == 0) {
            throw std::invalid_argument("LRUCache capacity must be greater than 0");
        }
    }

    // Returns the value associated with key, or std::nullopt if not found.
    // Marks the entry as most-recently-used.
    std::optional<V> get(const K& key) {
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        // Move the entry to the front of the list (most recently used).
        // splice moves the node from its current position to the front.
        // This does not invalidate iterators to other elements.
        list_.splice(list_.begin(), list_, it->second);
        return it->second->second;
    }

    // Inserts or updates the key-value pair. If the cache is at capacity,
    // evicts the least-recently-used entry.
    void put(const K& key, const V& value) {
        auto it = map_.find(key);
        if (it != map_.end()) {
            // Key exists: update value and move to front (most recently used).
            it->second->second = value;
            list_.splice(list_.begin(), list_, it->second);
            return;
        }

        // Key does not exist: insert new entry.
        // If at capacity, evict the least-recently-used (back of list).
        if (map_.size() == capacity_) {
            // The back of the list is the least recently used.
            auto lru_it = list_.back();
            map_.erase(lru_it.first);
            list_.pop_back();
        }

        // Insert at the front of the list (most recently used).
        list_.push_front(std::make_pair(key, value));
        map_[key] = list_.begin();
    }

    // Erases the entry with the given key. Returns true if the key was found
    // and erased, false otherwise.
    bool erase(const K& key) {
        auto it = map_.find(key);
        if (it == map_.end()) {
            return false;
        }
        // Remove from list and map.
        list_.erase(it->second);
        map_.erase(it);
        return true;
    }

    // Returns the number of entries currently in the cache.
    std::size_t size() const {
        return map_.size();
    }

    // Returns the maximum capacity of the cache.
    std::size_t capacity() const {
        return capacity_;
    }

    // Removes all entries from the cache.
    void clear() {
        map_.clear();
        list_.clear();
    }

    // Returns the value associated with key without changing its recency.
    // Useful for testing.
    std::optional<V> peek(const K& key) const {
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        return it->second->second;
    }

private:
    std::size_t capacity_;
    // List stores key-value pairs. Front = most recently used, back = least recently used.
    std::list<std::pair<K, V>> list_;
    // Map from key to iterator into the list. This allows O(1) lookup and O(1)
    // removal/movement via splice.
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> map_;
};

#endif // LRU_CACHE_H
